    'select' => '`child_id`'
));

// There is probably a way to do this part more efficiently...
$child_ids = array();
foreach( $result as $row ) {
    $child_ids[] = $row->child_id;
}

$children = Category::find( 'all', array( 
    'conditions' => array( '`id` in(?)', $child_ids )
));
