func TestSpfLoopSelf(t *testing.T) {
	res := loopResolver{"a.example.com": "v=spf1 include:a.example.com ~all"}
	rec, err := Parse("v=spf1 include:a.example.com ~all", res)
	t.Log(rec, err)
}

func TestSpfLoopTwoNode(t *testing.T) {
	res := loopResolver{
		"a.example.com": "v=spf1 include:b.example.com ~all",
		"b.example.com": "v=spf1 include:a.example.com ~all",
	}
	rec, err := Parse("v=spf1 include:a.example.com ~all", res)
	t.Log(rec, err)
}

func TestSpfLoopRedirect(t *testing.T) {
	res := loopResolver{"a.example.com": "v=spf1 redirect=a.example.com"}
	rec, err := Parse("v=spf1 redirect=a.example.com", res)
	t.Log(rec, err)
}

func TestSpfLoopRecoverDoesNotCatch(t *testing.T) {
	res := loopResolver{"a.example.com": "v=spf1 include:a.example.com ~all"}
