import java.util.*;

/**
 * Task Scheduler
 * -----------------------------------------------------
 * Combines two DSA concepts:
 *   1. Graph + Topological Sort (Kahn's Algorithm) -> respects task dependencies
 *   2. Min-Heap (PriorityQueue)                     -> among all "ready" tasks
 *                                                       (no pending dependencies),
 *                                                       picks the one with highest
 *                                                       priority / earliest deadline first
 *
 * Real-world analogy: build systems (Maven/Gradle) and CI pipelines
 * decide job order this exact way -> dependencies first, then priority.
 */

class Task implements Comparable<Task> {
    int id;
    String name;
    int priority;      // lower number = higher priority (1 = highest)
    int deadline;       // e.g. day number or time unit
    List<Integer> dependencies; // IDs of tasks that must finish before this one

    public Task(int id, String name, int priority, int deadline, List<Integer> dependencies) {
        this.id = id;
        this.name = name;
        this.priority = priority;
        this.deadline = deadline;
        this.dependencies = dependencies;
    }

    // Comparator logic for the min-heap:
    // 1) lower priority number comes first
    // 2) if tie, earlier deadline comes first
    @Override
    public int compareTo(Task other) {
        if (this.priority != other.priority) {
            return Integer.compare(this.priority, other.priority);
        }
        return Integer.compare(this.deadline, other.deadline);
    }

    @Override
    public String toString() {
        return String.format("[Task %d] %-15s (priority=%d, deadline=%d)",
                id, name, priority, deadline);
    }
}

public class TaskScheduler {

    private Map<Integer, Task> taskMap = new HashMap<>();
    private Map<Integer, List<Integer>> graph = new HashMap<>();   // task -> tasks that depend on it
    private Map<Integer, Integer> inDegree = new HashMap<>();      // task -> number of unresolved dependencies

    public void addTask(Task task) {
        taskMap.put(task.id, task);
        graph.putIfAbsent(task.id, new ArrayList<>());
        inDegree.putIfAbsent(task.id, 0);

        for (int depId : task.dependencies) {
            graph.putIfAbsent(depId, new ArrayList<>());
            graph.get(depId).add(task.id);              // depId -> task.id edge
            inDegree.put(task.id, inDegree.get(task.id) + 1);
        }
    }

    /**
     * Runs the scheduler:
     * - Uses a PriorityQueue as the "ready set" (indegree == 0)
     * - Each time a task completes, decrements indegree of its dependents
     * - If a dependent's indegree hits 0, it becomes "ready" and enters the heap
     * - Detects cycles: if not all tasks get scheduled, a cycle exists
     */
    public List<Task> schedule() {
        PriorityQueue<Task> readyQueue = new PriorityQueue<>();
        Map<Integer, Integer> indegreeCopy = new HashMap<>(inDegree);

        // seed the heap with all tasks that have no dependencies
        for (Task t : taskMap.values()) {
            if (indegreeCopy.get(t.id) == 0) {
                readyQueue.offer(t);
            }
        }

        List<Task> executionOrder = new ArrayList<>();

        while (!readyQueue.isEmpty()) {
            Task current = readyQueue.poll();
            executionOrder.add(current);

            for (int dependentId : graph.getOrDefault(current.id, Collections.emptyList())) {
                int updated = indegreeCopy.get(dependentId) - 1;
                indegreeCopy.put(dependentId, updated);
                if (updated == 0) {
                    readyQueue.offer(taskMap.get(dependentId));
                }
            }
        }

