  "where": [
    "exists",
    {
      "SELECT": {
        "from": { "ref": ["localized.msgfood.disassembly.ManageMRPCalculationsAppService.MRPCalculationHeaders"], "as": "$M2" },
        "columns": [{ "val": 1 }],
        "where": [
          { "ref": ["$M2", "ID"] }, "=", { "ref": ["$m", "mrpCalculationHeader_ID"] },
          "and",
          { "ref": ["$M2", "ID"] }, "=", { "val": "a5608fd3-3799-429f-8d86-1f3ebaf33816" }
        ]
      }
    }
